/**
 * 执行脚本并返回输出结果
 * @param {string} script 要执行的脚本命令
 * @param {ExecScriptOptions} options 执行选项
 * @returns {Promise<string|{stdout: string, stderr: string}>} 根据选项返回stdout或包含stdout和stderr的对象
 */
interface ExecScriptOptions {
    silent?: boolean;
    env?: NodeJS.ProcessEnv;
    maxBuffer?: number;
    encoding?: string;
    /**
     * 如何处理标准错误输出
     * - 'ignore': 忽略stderr (默认)
     * - 'throw': 当stderr有内容时抛出错误
     * - 'include': 将stderr包含在返回结果中
     */
    stderrHandling?: 'ignore' | 'throw' | 'include';
}
declare function execScript(script: string, options?: ExecScriptOptions): Promise<unknown>;

export { type ExecScriptOptions, execScript };
